        ZonedDateTime kirim = ZonedDateTime.of(
                LocalDateTime.of(2026, 8, 17, 22, 30), ZoneId.of("Asia/Jakarta"));
        ZonedDateTime diJayapura = kirim.withZoneSameInstant(ZoneId.of("Asia/Jayapura"));
        ZonedDateTime salah = kirim.withZoneSameLocal(ZoneId.of("Asia/Jayapura"));

        System.out.println(kirim);
        System.out.println(diJayapura);
        System.out.println(diJayapura.toLocalDate());
        System.out.println(salah);
    }
}

