import java.time.*;
import java.time.format.DateTimeFormatter;

public class Main {
    public static void main(String[] args) {
        ZonedDateTime live = ZonedDateTime.of(
                LocalDateTime.of(2026, 10, 30, 20, 0), ZoneId.of("Asia/Jakarta"));
        DateTimeFormatter jam = DateTimeFormatter.ofPattern("HH:mm");
        System.out.println(live.withZoneSameInstant(ZoneId.of("Asia/Makassar")).format(jam));
        System.out.println(live.withZoneSameInstant(ZoneId.of("Asia/Jayapura")).format(jam));
    }
}

